using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetch data from an external API endpoint and return the response body.")]
    public async Task<string> FetchApi(
        [Description("The full URL of the API endpoint to call")] string url,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching {Url}", url);

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}

using Microsoft.Extensions.AI;
using ModelContextProtocol.Server;
using System.ComponentModel;

[McpServerPromptType]
public static class SummarizationPrompts
{
    [McpServerPrompt, Description("Summarize the provided content into a concise single-sentence summary.")]
    public static ChatMessage Summarize(
        [Description("The text content to summarize")] string content) =>
        new(ChatRole.User, $"Summarize the following content into one concise sentence:\n\n{content}");
}

